import { AgentAnalytics } from "@upstash/agent-analytics";
import { Redis } from "@upstash/redis";

const analytics = new AgentAnalytics({
  redis: Redis.fromEnv(),
  retention: "7d",
});

await analytics.query.getIndex();

const since = new Date(Date.now() - 24 * 3600_000);
const totals = await analytics.query.aggregateBy({
  field: "provider",
  since,
});
const hourly = await analytics.query.timeseries({
  since,
  groupBy: "provider",
});

console.log(totals, hourly);

